// 设置的 shadcn 外观：一组设置是一个表单，字段、显示文字和校验规则来自 @go-tenon/shell 的 settingsModel
// （服务端的 rest.API.Settings）。可以用“保存”按钮，也可以修改后自动保存。

import { type Settings, type SettingsModel, useSettings } from "@go-tenon/shell"
import type { ReactNode } from "react"
import type { FieldValues } from "react-hook-form"
import { AutoSaveStatus, FormError, useApiForm, useAutoSave } from "@/components/tenon/form"
import { PageError, PageLoading } from "@/components/tenon/page"
import { defaultInput, type FieldInput, ResourceFormField } from "@/components/tenon/resource-page"
import { Button } from "@/components/ui/button"
import { Card, CardAction, CardContent, CardHeader, CardTitle } from "@/components/ui/card"

/** SettingsForm 的选项。 */
export interface SettingsFormProps {
  /** 设置的模型：settingsModel(settings.<名称>, kit, queryClient)。 */
  model: SettingsModel
  /** 修改后自动保存，不显示“保存”按钮。默认 false。 */
  autoSave?: boolean
  /** 覆盖某个字段的输入组件，与 ResourcePage 的 inputs 相同。 */
  inputs?: { [field: string]: FieldInput }
  /** 标题，默认是设置的显示文字（<名称>.title）。传 null 不显示。 */
  title?: ReactNode | null
}

/**
 * 设置的表单：读取设置作为初始值，按权限决定能否修改。没有保存的权限时只读。
 *
 *   <SettingsForm model={blogSettings} autoSave />
 */
export function SettingsForm({ model, autoSave = false, inputs = {}, title }: SettingsFormProps): ReactNode {
  const view = useSettings(model)
  if (view.loading) return <PageLoading rows={3} />
  if (!view.values) return <PageError error={view.error} retry={view.refetch} />
  return <Loaded view={view} values={view.values} autoSave={autoSave} inputs={inputs} title={title} />
}

/** 读到设置之后的表单：初始值只在第一次渲染时交给 react-hook-form。 */
function Loaded({
  view,
  values,
  autoSave,
  inputs,
  title,
}: {
  view: Settings
  values: Record<string, unknown>
  autoSave: boolean
  inputs: { [field: string]: FieldInput }
  title?: ReactNode | null
}): ReactNode {
  const { model } = view
  const schema = model.formSchema()
  const { form, onSubmit, formError, pending } = useApiForm<FieldValues>({
    schema,
    rules: model.ruleOptions,
    defaultValues: values,
    submit: (v) => view.save(v),
    guard: !autoSave,
  })
  const autosave = useAutoSave(form, {
    schema,
    rules: model.ruleOptions,
    save: (v) => view.save(v),
    enabled: autoSave && view.canSave,
  })
  const heading = title === undefined ? model.title : title
  return (
    <Card>
      {(heading || autoSave) && (
        <CardHeader>
          {heading && <CardTitle>{heading}</CardTitle>}
          {autoSave && (
            <CardAction>
              <AutoSaveStatus status={autosave.status} />
            </CardAction>
          )}
        </CardHeader>
      )}
      <CardContent>
        <form onSubmit={onSubmit} className="grid gap-4" noValidate>
          <fieldset disabled={!view.canSave} className="grid gap-4 disabled:opacity-70">
            <FormError error={formError} />
            {model.form.map((f) => (
              <ResourceFormField key={f.name} form={form} field={f} input={inputs[f.name] ?? defaultInput} />
            ))}
          </fieldset>
          {!autoSave && view.canSave && (
            <div>
              <Button type="submit" disabled={pending}>
                保存
              </Button>
            </div>
          )}
        </form>
      </CardContent>
    </Card>
  )
}

// 资源的 shadcn 外观：DataTable（TanStack Table）渲染列表，对话框中的 react-hook-form 渲染创建和修改的表单。
// 模型来自 @go-tenon/shell 的 resourceModel：列、筛选条件、表单字段、权限和接口都在定义中，页面只写需要覆盖的部分。

import { describeError } from "@go-tenon/client"
import {
  formValues,
  type ListRoute,
  type ResourceField,
  type ResourceModel,
  type ResourceRow,
  useResourceList,
  useResourceMutations,
} from "@go-tenon/shell"
import { Plus } from "lucide-react"
import { type ReactNode, useEffect, useMemo, useState } from "react"
import { Controller, type FieldValues, type UseFormReturn } from "react-hook-form"
import { DataTable, type DataTableColumn, type RowAction } from "@/components/tenon/data-table"
import { useConfirm } from "@/components/tenon/dialogs"
import { Field, FormError, useApiForm } from "@/components/tenon/form"
import { PageHeader } from "@/components/tenon/page"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"

/** 一个字段的输入组件。id 要放在控件上，标签才能指向它。 */
export type FieldInput = (props: {
  field: ResourceField
  id: string
  value: unknown
  onChange: (v: unknown) => void
  invalid?: boolean
}) => ReactNode

/** ResourcePage 的选项：没有覆盖时全部按定义渲染。 */
export interface ResourcePageProps {
  model: ResourceModel
  /** 列表的路由：validateSearch 是 model.listSearch。 */
  route: ListRoute<Record<string, unknown>>
  /** 覆盖某一列的显示。 */
  render?: { [field: string]: (value: unknown, row: ResourceRow) => ReactNode }
  /** 覆盖某个表单字段的输入组件。 */
  inputs?: { [field: string]: FieldInput }
  /** 行上的额外操作，排在定义中的操作之后。 */
  rowActions?: (row: ResourceRow) => RowAction[]
  /** 页头右侧的额外按钮，排在“新建”之前。 */
  actions?: ReactNode
}

const ALL = "__all__"

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" })
const dateOnly = new Intl.DateTimeFormat(undefined, { dateStyle: "medium" })

/** 按字段的类型显示一个值：枚举显示文字，布尔显示是否，时间按本地格式，标签逐个显示。 */
export function FieldValue({
  model,
  field,
  value,
}: {
  model: ResourceModel
  field: ResourceField
  value: unknown
}): ReactNode {
  if (value === undefined || value === null || value === "") return <span className="text-muted-foreground">-</span>
  switch (field.kind) {
    case "boolean":
      return value ? <Badge>是</Badge> : <Badge variant="outline">否</Badge>
    case "select":
      return <Badge variant="secondary">{String(model.display(field, value))}</Badge>
    case "multiselect":
    case "tags":
      return (
        <span className="flex flex-wrap gap-1">
          {((model.display(field, value) as unknown[]) ?? []).map((v) => (
            <Badge key={String(v)} variant="outline">
              {String(v)}
            </Badge>
          ))}
        </span>
      )
    case "datetime":
    case "date": {
      const d = new Date(String(value))
      return Number.isNaN(d.getTime()) ? String(value) : (field.kind === "date" ? dateOnly : dateTime).format(d)
    }
    case "json":
      return <code className="text-xs">{JSON.stringify(value)}</code>
    default:
      return String(value)
  }
}

/** datetime-local 输入框的值（本地时间）与 ISO 字符串之间的转换。 */
const toLocalInput = (iso: unknown) => {
  if (!iso) return ""
  const d = new Date(String(iso))
  if (Number.isNaN(d.getTime())) return ""
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
}

/** 按字段的类型选择输入组件。时间以 ISO 字符串保存，与接口相同；标签用逗号分隔。 */
export const defaultInput: FieldInput = ({ field, id, value, onChange, invalid }) => {
  switch (field.kind) {
    case "number":
      return (
        <Input
          id={id}
          type="number"
          aria-invalid={invalid}
          value={value === undefined || value === null ? "" : String(value)}
          onChange={(e) => onChange(e.target.value === "" ? undefined : Number(e.target.value))}
        />
      )
    case "boolean":
      return <Checkbox id={id} checked={!!value} onCheckedChange={(v) => onChange(v === true)} />
    case "select":
      return (
        <Select value={(value as string) ?? ""} onValueChange={(v) => onChange(v)}>
          <SelectTrigger id={id} aria-invalid={invalid} className="w-full">
            <SelectValue placeholder="请选择" />
          </SelectTrigger>
          <SelectContent>
            {field.options?.map((o) => (
              <SelectItem key={o.value} value={o.value}>
                {o.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )
    case "multiselect": {
      const selected = (value as string[] | undefined) ?? []
      return (
        <fieldset id={id} className="flex flex-wrap gap-3">
          {field.options?.map((o) => (
            <div key={o.value} className="flex items-center gap-1.5">
              <Checkbox
                id={`${id}-${o.value}`}
                checked={selected.includes(o.value)}
                onCheckedChange={(v) =>
                  onChange(v === true ? [...selected, o.value] : selected.filter((s) => s !== o.value))
                }
              />
              <Label htmlFor={`${id}-${o.value}`} className="font-normal">
                {o.label}
              </Label>
            </div>
          ))}
        </fieldset>
      )
    }
    case "tags":
      return (
        <Input
          id={id}
          aria-invalid={invalid}
          placeholder="用逗号分隔"
          defaultValue={((value as string[] | undefined) ?? []).join(", ")}
          onChange={(e) =>
            onChange(
              e.target.value
                .split(/[,，]/)
                .map((s) => s.trim())
                .filter(Boolean),
            )
          }
        />
      )
    case "date":
      return (
        <Input
          id={id}
          type="date"
          aria-invalid={invalid}
          value={(value as string) ?? ""}
          onChange={(e) => onChange(e.target.value || undefined)}
        />
      )
    case "datetime":
      return (
        <Input
          id={id}
          type="datetime-local"
          aria-invalid={invalid}
          value={toLocalInput(value)}
          onChange={(e) => onChange(e.target.value ? new Date(e.target.value).toISOString() : undefined)}
        />
      )
    case "json":
      return <Textarea id={id} value={JSON.stringify(value ?? null)} disabled />
    default:
      return (
        <Input
          id={id}
          aria-invalid={invalid}
          value={(value as string) ?? ""}
          onChange={(e) => onChange(e.target.value)}
        />
      )
  }
}

/** 列表上方的搜索和筛选：搜索在输入停顿后写进地址，筛选立即写进地址。 */
function Toolbar({
  model,
  list,
}: {
  model: ResourceModel
  list: ReturnType<typeof useResourceList>["list"]
}): ReactNode {
  const filters = list.filters as Record<string, unknown>
  const q = model.search && typeof filters[model.search] === "string" ? (filters[model.search] as string) : ""
  const [value, setValue] = useState(q)
  useEffect(() => setValue(q), [q])
  useEffect(() => {
    if (!model.search || value === q) return
    const t = setTimeout(() => list.setFilters({ [model.search as string]: value || undefined }), 300)
    return () => clearTimeout(t)
  }, [value, q, list, model.search])
  if (!model.search && model.filters.length === 0) return null
  return (
    <div className="flex flex-wrap items-center gap-2">
      {model.search && (
        <Input
          aria-label="搜索"
          placeholder="搜索…"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          className="h-9 w-64"
        />
      )}
      {model.filters.map((f) =>
        f.options && f.kind === "select" ? (
          <Select
            key={f.name}
            value={(filters[f.name] as string) ?? ALL}
            onValueChange={(v) => list.setFilters({ [f.name]: v === ALL ? undefined : v })}
          >
            <SelectTrigger aria-label={f.label} className="h-9 w-40">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL}>全部{f.label}</SelectItem>
              {f.options.map((o) => (
                <SelectItem key={o.value} value={o.value}>
                  {o.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : (
          <Input
            key={f.name}
            aria-label={f.label}
            placeholder={f.label}
            defaultValue={(filters[f.name] as string) ?? ""}
            onKeyDown={(e) => {
              if (e.key === "Enter") list.setFilters({ [f.name]: e.currentTarget.value || undefined })
            }}
            className="h-9 w-40"
          />
        ),
      )}
    </div>
  )
}

/** 创建和修改的表单：字段、校验规则（与服务端相同）来自定义，服务端的字段错误显示在输入框下面。 */
export function ResourceForm({
  model,
  row,
  inputs = {},
  onDone,
}: {
  model: ResourceModel
  /** 修改的行；新建时为空。 */
  row?: ResourceRow
  inputs?: ResourcePageProps["inputs"]
  onDone(): void
}): ReactNode {
  const { save } = useResourceMutations(model)
  const { form, onSubmit, formError, pending } = useApiForm<FieldValues>({
    schema: model.formSchema(row ? "update" : "create"),
    rules: model.ruleOptions,
    defaultValues: formValues(model, row),
    submit: async (values) => {
      await save.mutateAsync({ key: row ? model.rowKey(row) : undefined, values })
      onDone()
    },
    guard: false,
  })
  return (
    <form onSubmit={onSubmit} className="grid gap-4" noValidate>
      <FormError error={formError} />
      {model.form.map((f) => (
        <ResourceFormField key={f.name} form={form} field={f} input={inputs[f.name] ?? defaultInput} />
      ))}
      <DialogFooter>
        <Button type="submit" disabled={pending}>
          保存
        </Button>
      </DialogFooter>
    </form>
  )
}

/** 表单中的一个字段：标签、输入组件和错误提示。设置的表单（SettingsForm）也用它。 */
export function ResourceFormField({
  form,
  field,
  input: FieldInputComponent,
}: {
  form: UseFormReturn<FieldValues>
  field: ResourceField
  input: FieldInput
}) {
  return (
    <Field form={form} name={field.name} label={field.required ? `${field.label} *` : field.label}>
      {(p) => (
        <Controller
          control={form.control}
          name={field.name}
          render={({ field: c }) => (
            <FieldInputComponent
              field={field}
              id={p.id}
              value={c.value}
              onChange={c.onChange}
              invalid={p["aria-invalid"]}
            />
          )}
        />
      )}
    </Field>
  )
}

/**
 * 资源的页面：页头、搜索和筛选、表格、新建和修改的对话框、删除和其他操作，按权限显示按钮。
 * 删除和带 Confirm 的操作用 useConfirm 询问，根路由中要有 ConfirmProvider。
 *
 *	export const Route = createFileRoute("/_app/articles")({ validateSearch: articles.listSearch, component: () => <ResourcePage model={articles} route={Route} /> })
 */
export function ResourcePage({ model, route, render = {}, inputs, rowActions, actions }: ResourcePageProps): ReactNode {
  const view = useResourceList(model, route)
  const { remove, run } = useResourceMutations(model)
  const confirm = useConfirm()
  const [editing, setEditing] = useState<{ row?: ResourceRow } | undefined>()
  const [failure, setFailure] = useState<unknown>()

  const attempt = async (go: () => Promise<unknown>) => {
    setFailure(undefined)
    try {
      await go()
    } catch (err) {
      setFailure(err)
    }
  }

  const columns = useMemo<DataTableColumn<ResourceRow>[]>(
    () =>
      model.columns.map((f) => ({
        id: f.name,
        accessorKey: f.name,
        header: f.label,
        enableSorting: f.sortable,
        cell: ({ row }) =>
          render[f.name]?.(row.original[f.name], row.original) ?? (
            <FieldValue model={model} field={f} value={row.original[f.name]} />
          ),
      })),
    [model, render],
  )

  const menu = (row: ResourceRow): RowAction[] => {
    const key = model.rowKey(row)
    const items: RowAction[] = []
    if (view.can.update) items.push({ label: "修改", onSelect: () => setEditing({ row }) })
    for (const a of model.actions) {
      if (!view.can.action(a.name)) continue
      items.push({
        label: a.label,
        destructive: a.danger,
        onSelect: () =>
          void (async () => {
            if (a.confirm && !(await confirm({ title: `${a.label}这一项？`, action: a.label, destructive: a.danger })))
              return
            await attempt(() => run.mutateAsync({ action: a.name, key }))
          })(),
      })
    }
    items.push(...(rowActions?.(row) ?? []))
    if (view.can.delete) {
      items.push({
        label: "删除",
        destructive: true,
        onSelect: () =>
          void (async () => {
            if (!(await confirm({ title: "删除这一项？", action: "删除", destructive: true }))) return
            await attempt(() => remove.mutateAsync(key))
          })(),
      })
    }
    return items
  }

  return (
    <div className="flex flex-col gap-4">
      <PageHeader title={model.title}>
        {actions}
        {view.can.create && (
          <Button onClick={() => setEditing({})}>
            <Plus />
            新建
          </Button>
        )}
      </PageHeader>
      {failure ? (
        <p role="alert" className="text-sm text-destructive">
          {describeError(failure).message}
        </p>
      ) : null}
      <DataTable
        columns={columns}
        data={view.loading ? undefined : view.rows}
        total={view.total}
        list={view.list}
        error={view.error}
        retry={view.refetch}
        rowKey={model.rowKey}
        rowActions={menu}
        toolbar={<Toolbar model={model} list={view.list} />}
      />
      <Dialog open={!!editing} onOpenChange={(open) => !open && setEditing(undefined)}>
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>
              {editing?.row ? "修改" : "新建"}
              {model.title}
            </DialogTitle>
          </DialogHeader>
          {editing && (
            <ResourceForm model={model} row={editing.row} inputs={inputs} onDone={() => setEditing(undefined)} />
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}

// 资源表格：服务端分页、排序和筛选，状态保存在地址中（@go-tenon/shell 的 useList），基于 TanStack Table。
// 另有列表工具栏、行操作菜单和状态标签。

import { type ListState, type Selection, useTabActive } from "@go-tenon/shell"
import {
  type ColumnDef,
  flexRender,
  type RowData,
  type RowSelectionState,
  rowSelectionFeature,
  rowSortingFeature,
  type SortingState,
  tableFeatures,
  useTable,
} from "@tanstack/react-table"
import { ArrowDown, ArrowUp, ArrowUpDown, ChevronLeft, ChevronRight, MoreHorizontal } from "lucide-react"
import { type ReactNode, useEffect, useState } from "react"
import { PageEmpty, PageError, PageLoading } from "@/components/tenon/page"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"

/** DataTable 用到的表格功能：排序和行选择。分页和排序都由服务端完成，没有登记客户端的行模型。 */
const features = tableFeatures({ rowSortingFeature, rowSelectionFeature })

/** DataTable 的功能集，自己用 TanStack Table 的类型（Row、Table 等）时作为第一个类型参数。 */
export type DataTableFeatures = typeof features

/**
 * DataTable 的列定义：TanStack Table 的 ColumnDef，功能集固定为 DataTable 的。
 * 值的类型因列而异，所以是 any；单独声明一列时可以写 ColumnDef<DataTableFeatures, T, string> 得到更准确的类型。
 */
// biome-ignore lint/suspicious/noExplicitAny: 一个列数组中各列的值类型不同
export type DataTableColumn<T extends RowData> = ColumnDef<DataTableFeatures, T, any>

/** 读取中的空数据：表格的输入保持稳定，不在每次渲染时换成新的数组。 */
const noRows: never[] = []

/** DataTable 的选项。 */
export interface DataTableProps<T extends RowData> {
  columns: DataTableColumn<T>[]
  /** 当前页的数据；读取中为 undefined。 */
  data?: T[]
  /** 符合条件的总数，用于分页。 */
  total?: number
  /** 列表的状态：useList(Route)。分页、排序保存在地址中，由服务端完成。 */
  list: ListState<Record<string, unknown>>
  /** 读取失败时的错误和重试。 */
  error?: unknown
  retry?: () => void
  /** 行的标识，默认是 row.id。 */
  rowKey?: (row: T) => string
  /** 选中项（useSelection）：有它时第一列是复选框，用于批量操作。 */
  selection?: Selection<string>
  /** 每一行的操作，例如编辑、删除。 */
  rowActions?: (row: T) => RowAction[]
  /** 表格上方的工具栏，例如 <ListToolbar>。 */
  toolbar?: ReactNode
  empty?: ReactNode
}

/** 行操作。 */
export interface RowAction {
  label: string
  onSelect: () => void
  destructive?: boolean
  disabled?: boolean
}

/** 行操作菜单（“⋯”）。 */
export function RowActions({ actions }: { actions: RowAction[] }): ReactNode {
  if (actions.length === 0) return null
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" className="size-8" aria-label="操作">
          <MoreHorizontal />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {actions.map((a) => (
          <DropdownMenuItem
            key={a.label}
            disabled={a.disabled}
            variant={a.destructive ? "destructive" : "default"}
            onSelect={a.onSelect}
          >
            {a.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

/** 状态标签：tone 决定颜色。文字通常来自生成的 enums.ts 中的显示文字。 */
export function StatusBadge({
  children,
  tone = "default",
}: {
  children: ReactNode
  tone?: "default" | "success" | "warning" | "error" | "muted"
}): ReactNode {
  const tones = {
    default: "",
    success: "border-transparent bg-success text-success-foreground",
    warning: "border-transparent bg-warning text-warning-foreground",
    error: "border-transparent bg-destructive text-white",
    muted: "border-transparent bg-muted text-muted-foreground",
  }
  return (
    <Badge variant={tone === "default" ? "secondary" : "outline"} className={tones[tone]}>
      {children}
    </Badge>
  )
}

/** 列表工具栏：关键词搜索（查询参数 q）和其他筛选、操作。输入停顿后才更新地址。 */
export function ListToolbar({
  list,
  placeholder = "搜索…",
  children,
}: {
  list: ListState<Record<string, unknown>>
  placeholder?: string
  children?: ReactNode
}): ReactNode {
  const q = typeof list.filters.q === "string" ? list.filters.q : ""
  const [value, setValue] = useState(q)
  useEffect(() => setValue(q), [q])
  useEffect(() => {
    if (value === q) return
    const t = setTimeout(() => list.setFilters({ q: value || undefined }), 300)
    return () => clearTimeout(t)
  }, [value, q, list])
  return (
    <div className="flex flex-wrap items-center gap-2">
      <Input value={value} onChange={(e) => setValue(e.target.value)} placeholder={placeholder} className="h-9 w-64" />
      {children}
    </div>
  )
}

/**
 * 资源表格：
 *
 *   const list = useList(Route)
 *   const articles = useQuery({ queryKey: ["article", "list", list.params], queryFn: () => api.article.list(list.params) })
 *   <DataTable columns={columns} data={articles.data?.items} total={articles.data?.total} list={list} error={articles.error} />
 *
 * 点击列头按这一列排序（列的 id 是排序参数），再点一次反向，第三次恢复默认。
 */
export function DataTable<T extends RowData>({
  columns,
  data,
  total = 0,
  list,
  error,
  retry,
  rowKey = (row) => String((row as { id?: unknown }).id),
  selection,
  rowActions,
  toolbar,
  empty,
}: DataTableProps<T>): ReactNode {
  const active = useTabActive()
  const sorting: SortingState = list.tableState.sorting
  const rowSelection: RowSelectionState = Object.fromEntries([...(selection?.keys ?? [])].map((k) => [k, true]))
  const all: DataTableColumn<T>[] = [
    ...(selection
      ? [
          {
            id: "_select",
            header: ({ table }) => (
              <Checkbox
                aria-label="选择本页"
                checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")}
                onCheckedChange={(v) => table.toggleAllPageRowsSelected(Boolean(v))}
              />
            ),
            cell: ({ row }) => (
              <Checkbox
                aria-label="选择"
                checked={row.getIsSelected()}
                onCheckedChange={(v) => row.toggleSelected(Boolean(v))}
              />
            ),
            enableSorting: false,
          } satisfies DataTableColumn<T>,
        ]
      : []),
    ...columns,
    ...(rowActions
      ? [
          {
            id: "_actions",
            header: () => null,
            cell: ({ row }) => <RowActions actions={rowActions(row.original)} />,
            enableSorting: false,
          } satisfies DataTableColumn<T>,
        ]
      : []),
  ]
  // 数据已经是服务端分页、排序后的一页：表格只负责渲染、列头排序的切换和行选择。
  const table = useTable({
    features,
    data: data ?? noRows,
    columns: all,
    getRowId: rowKey,
    manualSorting: true,
    enableSortingRemoval: true,
    state: { sorting, rowSelection },
    onSortingChange: (updater) => {
      const next = typeof updater === "function" ? updater(sorting) : updater
      list.setSort(next[0] ? { field: next[0].id, desc: next[0].desc } : undefined)
    },
    onRowSelectionChange: (updater) => {
      const next = typeof updater === "function" ? updater(rowSelection) : updater
      selection?.set(Object.keys(next).filter((k) => next[k]))
    },
  })
  const pages = Math.max(1, Math.ceil(total / list.perPage))
  return (
    <div className="space-y-3" data-active={active}>
      {toolbar}
      {error ? (
        <PageError error={error} retry={retry} />
      ) : data === undefined ? (
        <PageLoading />
      ) : (
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              {table.getHeaderGroups().map((group) => (
                <TableRow key={group.id}>
                  {group.headers.map((header) => {
                    const sorted = header.column.getIsSorted()
                    return (
                      <TableHead key={header.id}>
                        {header.isPlaceholder ? null : header.column.getCanSort() ? (
                          <button
                            type="button"
                            className="inline-flex items-center gap-1 hover:text-foreground"
                            onClick={header.column.getToggleSortingHandler()}
                          >
                            {flexRender(header.column.columnDef.header, header.getContext())}
                            {sorted === "asc" ? (
                              <ArrowUp className="size-3" />
                            ) : sorted === "desc" ? (
                              <ArrowDown className="size-3" />
                            ) : (
                              <ArrowUpDown className="size-3 opacity-40" />
                            )}
                          </button>
                        ) : (
                          flexRender(header.column.columnDef.header, header.getContext())
                        )}
                      </TableHead>
                    )
                  })}
                </TableRow>
              ))}
            </TableHeader>
            <TableBody>
              {table.getRowModel().rows.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={all.length}>
                    <PageEmpty>{empty}</PageEmpty>
                  </TableCell>
                </TableRow>
              ) : (
                table.getRowModel().rows.map((row) => (
                  <TableRow key={row.id} data-state={row.getIsSelected() ? "selected" : undefined}>
                    {row.getAllCells().map((cell) => (
                      <TableCell key={cell.id}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</TableCell>
                    ))}
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      )}
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span>
          共 {total} 条{selection && selection.keys.size > 0 ? `，已选 ${selection.keys.size} 条` : ""}
        </span>
        <div className="flex items-center gap-2">
          <span>
            第 {list.page} / {pages} 页
          </span>
          <Button
            variant="outline"
            size="icon"
            className="size-8"
            aria-label="上一页"
            disabled={list.page <= 1}
            onClick={() => list.setPage(list.page - 1)}
          >
            <ChevronLeft />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="size-8"
            aria-label="下一页"
            disabled={list.page >= pages}
            onClick={() => list.setPage(list.page + 1)}
          >
            <ChevronRight />
          </Button>
        </div>
      </div>
    </div>
  )
}

